export function mountInstalled150(view,bench,id){const m=SERVICE_LOCATIONS150[id];if(!m)throw Error('Equipo no disponible');bench.group.position.set(...m.xyz);bench.group.scale.setScalar(m.scale);bench.group.updateMatrixWorld(true);bench.mounted150={...m,id};}
export function installedContext150(v,part){v.isolated=false;v.exploded=false;v.interior=true;v.doorsVisible=true;v.cameraPreset134='inspection';for(const g of v.parts.values()){g.position.set(0,0,0);g.visible=true;}v.parts.get('roof')?.visible&&(v.parts.get('roof').visible=false);v.model.userData.frontWall&&(v.model.userData.frontWall.visible=false);v.spread144?.reset();for(const r of v.cabinets135?.rows||[]){r.open=r.id===part;r.amount=r.open?1:0;r.door.visible=true;r.door.quaternion.copy(r.open?r.opened:r.closed);}v.cabinets135?.render();}
